#include <stdio.h>

int main(void) {
    int L, C;
    char grid[105][105];

    if (scanf("%d %d", &L, &C) != 2) return 0;

    int sr = -1, sc = -1;
    for (int r = 0; r < L; r++) {
        scanf("%s", grid[r]);
        for (int c = 0; c < C; c++) {
            if (grid[r][c] == 'o') {
                sr = r;
                sc = c;
            }
        }
    }

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    int pr = sr, pc = sc;
    int cr = -1, cc = -1;

    for (int d = 0; d < 4; d++) {
        int nr = sr + dr[d], nc = sc + dc[d];
        if (nr >= 0 && nr < L && nc >= 0 && nc < C && grid[nr][nc] == 'H') {
            cr = nr;
            cc = nc;
            break;
        }
    }

    while (1) {
        int nr = -1, nc = -1;
        for (int d = 0; d < 4; d++) {
            int r = cr + dr[d], c = cc + dc[d];
            if (r >= 0 && r < L && c >= 0 && c < C &&
                grid[r][c] == 'H' && (r != pr || c != pc)) {
                nr = r;
                nc = c;
                break;
            }
        }

        if (nr == -1) break;

        pr = cr;
        pc = cc;
        cr = nr;
        cc = nc;
    }

    printf("%d %d\n", cr + 1, cc + 1);
    return 0;
}
